                  {fig(rateOf(rates.data, g, `${m}-01`) ?? NA)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 40.5, Component: RateCalendar });

